          severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
          title: { type: 'string' },
          detail: { type: 'string', description: 'what is wrong, with the code quoted' },
          scenario: { type: 'string', description: 'concrete input/state -> wrong result' },
        },
        required: ['file', 'line', 'severity', 'title', 'detail', 'scenario'],
      },
    },
    coverage: { type: 'string', description: 'what you read and what you skipped' },
  },
  required: ['findings', 'coverage'],
}

const VERDICT = {
  type: 'object',
  properties: {
    real: { type: 'boolean' },
    severity: { type: 'string', enum: ['blocker', 'major', 'minor', 'none'] },
    reasoning: { type: 'string' },
    comment: { type: 'string', description: 'if real: the review comment to post on that line, 2-5 sentences, concrete, no preamble' },
  },
  required: ['real', 'severity', 'reasoning', 'comment'],
}

const RULES = `You are reviewing PR #363 in /home/user/burpsy (branch backlog-b9 into master). Base ${BASE}, head ${HEAD}; both are fetched.
STRICT: read-only. Never checkout, switch, stash, reset or edit files in /home/user/burpsy — other agents share it. Read code with \`git show ${HEAD}:<path>\` and diffs with \`git diff -w ${BASE}...${HEAD} -- <paths>\` (-w: much of the diff is reformatting). You may run go tests only from a private worktree: \`git worktree add /tmp/rv-$RANDOM ${HEAD}\` (remove it when done).`

const reviewed = await pipeline(
  SLICES,
  s => agent(`${RULES}

Your slice: ${s.paths}
Focus: ${s.focus}

Review every changed file in your slice (use \`git diff -w --stat ${BASE}...${HEAD} -- ${s.paths}\` for the list). Report only defects introduced by this PR that a careful reviewer would block or fix: bugs, security holes, races, regressions, tests that cannot fail. No style nits, no praise, no speculation without a traced path. Each finding needs a concrete scenario. Zero findings is a fine answer.`,
    { label: `review:${s.key}`, phase: 'Review', schema: FINDINGS }),
  (r, s) => {
    if (!r) return []
    log(`${s.key}: ${r.findings.length} finding(s)`)
    return parallel(r.findings.map(f => () =>
      agent(`${RULES}

A reviewer claims this defect in PR #363. Try hard to REFUTE it: read the actual head code, callers, and tests; check whether it predates the PR (\`git show ${BASE}:<path>\`), whether a guard elsewhere prevents it, whether the scenario is reachable. Default to real=false if you cannot confirm it from code.

File: ${f.file}:${f.line}
Severity claimed: ${f.severity}
Title: ${f.title}
Detail: ${f.detail}
Scenario: ${f.scenario}`,
        { label: `verify:${s.key}:${f.file.split('/').pop()}:${f.line}`, phase: 'Verify', schema: VERDICT })
        .then(v => ({ ...f, slice: s.key, verdict: v }))))
  },
)

const all = reviewed.flat().filter(Boolean)
const confirmed = all.filter(f => f.verdict && f.verdict.real && f.verdict.severity !== 'none')
const rejected = all.filter(f => !(f.verdict && f.verdict.real))
return { confirmed, rejectedCount: rejected.length, rejected: rejected.map(f => ({ file: f.file, line: f.line, title: f.title, why: f.verdict ? f.verdict.reasoning : 'verifier died' })) }

