const followFixPrompt = (a, v) => `${CONTEXT}

A verifier checked the fixes in this area: ${a.scope}
It found these problems remaining at ${HEAD}:
${JSON.stringify({ items: v.items.filter(i => i.status !== 'fixed'), new_defects: v.new_defects }, null, 2)}

Your job: re-check each problem against the code first (drop any that are wrong, say why), then FIX the real ones.

${COMMIT_RULES.replace('BRANCH', 'pr363fix/follow-' + a.key)}`

const [verified, fixed] = await Promise.all([
  pipeline(
    VERIFY_AREAS,
    a => agent(verifyPrompt(a), { label: `verify:${a.key}`, phase: 'Verify', schema: VERIFY_SCHEMA }),
    (v, a) => {
      if (!v) return null
      const open = v.items.filter(i => i.status !== 'fixed').length + v.new_defects.length
      log(`verify ${a.key}: ${v.items.length} checked, ${open} open`)
      if (!open) return { area: a.key, verify: v, follow: null }
      return agent(followFixPrompt(a, v), { label: `follow-fix:${a.key}`, phase: 'Fix', schema: FIX_SCHEMA, isolation: 'worktree' })
        .then(fx => ({ area: a.key, verify: v, follow: fx }))
    },
  ),
  parallel(FIXES.map(f => () =>
    agent(fixPrompt(f), { label: `fix:${f.key}`, phase: 'Fix', schema: FIX_SCHEMA, isolation: 'worktree' })
      .then(r => ({ key: f.key, result: r })))),
])

return { verified: verified.filter(Boolean), fixed: fixed.filter(Boolean) }

