	t.Helper()
	l, err := vulnapp.StartListener(listener)
	if err != nil {
		t.Fatalf("start %s: %v", listener, err)
	}
	t.Cleanup(func() { l.Close() })
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	defer cancel()
