	run := newAuditRun(AuditConfig{MaxUnitVariantsPerUnit: 2})
	if run.unitVariantCapped("h/p#fp1") || run.unitVariantCapped("h/p#fp2") {
		t.Fatal("the first two variants of one endpoint are admitted")
